begin;
create extension if not exists pgtap with schema extensions;
set search_path=public,extensions;
select no_plan();

insert into auth.users(id,email) values
 ('00000000-0000-4000-8000-000000313001','blog-owner@veyocast.test'),
 ('00000000-0000-4000-8000-000000313002','blog-admin@veyocast.test'),
 ('00000000-0000-4000-8000-000000313003','blog-viewer@veyocast.test'),
 ('00000000-0000-4000-8000-000000313004','blog-tenant-a@veyocast.test'),
 ('00000000-0000-4000-8000-000000313005','blog-tenant-b@veyocast.test');
insert into public.profiles(id,display_name) select id,'Blog operator' from auth.users where email like 'blog-%@veyocast.test';
insert into public.platform_memberships(user_id,role) values
 ('00000000-0000-4000-8000-000000313001','platform_owner'),
 ('00000000-0000-4000-8000-000000313002','platform_admin'),
 ('00000000-0000-4000-8000-000000313003','platform_viewer');
insert into public.tenants(id,name,slug) values
 ('10000000-0000-4000-8000-000000313001','Blog A','blog-tenant-a'),
 ('10000000-0000-4000-8000-000000313002','Blog B','blog-tenant-b');
insert into public.tenant_memberships(tenant_id,user_id,role) values
 ('10000000-0000-4000-8000-000000313001','00000000-0000-4000-8000-000000313004','tenant_admin'),
 ('10000000-0000-4000-8000-000000313002','00000000-0000-4000-8000-000000313005','tenant_admin');
create temporary table fixture(payload jsonb,media jsonb,intent jsonb,media_receipt jsonb,first_write jsonb,first_publish jsonb,token_id uuid,api_intent jsonb,api_receipt jsonb);
insert into fixture(payload,media) values(
 '{"type":"blog","locale":"nl-NL","title":"Clubschermen op wedstrijddag","slug":"clubschermen-op-wedstrijddag","excerpt":"Een actueel wedstrijdprogramma.","content":{"type":"doc","content":[{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Begin met de wedstrijddag"}]},{"type":"paragraph","content":[{"type":"text","text":"Controleer het thuisprogramma."}]}]},"seoTitle":"Clubschermen | VeyoCast","seoDescription":"Actuele informatie voor de vereniging.","authorId":"redactie","categoryId":"clubtv","tags":["clubschermen"],"hero":null,"ogImageAssetId":null}',
 '{"sha256":"aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa","outputSha256":"bbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbb","type":"image/png","width":800,"height":1200,"bytes":1234}');
grant all on fixture to anon,authenticated,service_role;

select ok((select bool_and(relrowsecurity) from pg_class where oid in ('public.platform_blog_posts'::regclass,'public.platform_blog_revisions'::regclass,'public.platform_blog_assets'::regclass,'private.platform_blog_receipts'::regclass,'private.platform_blog_tokens'::regclass)),'all content and secret tables enable RLS');
select ok((select reloptions @> array['security_invoker=true'] from pg_class where oid='public.platform_blog_publications'::regclass),'publication view invokes reader RLS');
select ok((select bool_and(not has_function_privilege('anon',p.oid,'EXECUTE')) from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname in ('public','private') and p.proname like 'blog_%'),'new blog functions add no anonymous command or definer access');
select ok((select bool_and(p.proconfig @> array['search_path=""']) from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname in ('public','private') and p.proname like 'blog_%' and p.prosecdef),'every new definer function fixes its search path');
select is((select public from storage.buckets where id='platform_blog_media'),false,'blog bucket remains private');
select is((select file_size_limit::bigint from storage.buckets where id='platform_blog_media'),8388608::bigint,'database and HTTP share the eight MiB media ceiling');
set local role anon;
select throws_ok($$select public.blog_command('veyocast','test','list',null,'{}',null,null)$$,'42501',null,'anonymous cannot invoke editorial commands');
select throws_ok($$select * from private.platform_blog_tokens$$,'42501',null,'anonymous cannot read credential hashes');
reset role;
set local role authenticated;
select set_config('request.jwt.claim.sub','00000000-0000-4000-8000-000000313001',true);
select set_config('request.jwt.claim.aal','aal1',true);
select throws_ok($$select public.blog_configure_site('veyocast','test','http://localhost:3002')$$,'PT403','PERMISSION_DENIED','AAL1 cannot configure destination');
select set_config('request.jwt.claim.aal','aal2',true);
select lives_ok($$select public.blog_configure_site('veyocast','test','http://localhost:3002')$$,'owner configures explicit isolated origin');
select is(public.blog_command('veyocast','test','capabilities',null,'{}',null,null)#>>'{body,publicOrigin}','http://localhost:3002','human destination preflight reports the authoritative configured origin');
select throws_ok($$select public.blog_configure_site('veyocast','production','http://localhost:3002')$$,'23514',null,'production requires HTTPS');
select lives_ok($$select public.blog_configure_site('veyocast','staging','https://blog-stage.example.test')$$,'separate environment is explicit');
select set_config('request.jwt.claim.aal','aal1',true);
select throws_ok($$select public.blog_authorize_media_upload('veyocast','test')$$,'PT403','PERMISSION_DENIED','AAL1 cannot authorize expensive image processing');
select set_config('request.jwt.claim.aal','aal2',true);
select set_config('request.jwt.claim.sub','00000000-0000-4000-8000-000000313004',true);
select throws_ok($$select public.blog_authorize_media_upload('veyocast','test')$$,'PT403','PERMISSION_DENIED','tenant cannot authorize platform media processing');
select set_config('request.jwt.claim.sub','00000000-0000-4000-8000-000000313003',true);
select throws_ok($$select public.blog_authorize_media_upload('veyocast','test')$$,'PT403','PERMISSION_DENIED','platform viewer cannot authorize image processing');
select set_config('request.jwt.claim.sub','00000000-0000-4000-8000-000000313001',true);
select throws_ok($$select public.blog_authorize_media_upload('unknown-site','test')$$,'PT404','NOT_FOUND','image processing requires an explicitly configured destination');
select is(public.blog_authorize_media_upload('veyocast','test')->>'allowed','true','AAL2 editor reserves processing capacity before decoding');
select count(public.blog_authorize_media_upload('veyocast','test')) from generate_series(1,29);
select is(public.blog_authorize_media_upload('veyocast','test')->>'code','RATE_LIMITED','human media capacity is durably limited to thirty per minute');
reset role;
select is((select requests from private.platform_blog_human_media_limits),31,'denied human media counter saturates without unbounded growth');
select is((select count(*)::integer from private.platform_blog_human_media_limits),1,'human media counter uses one row per actor and destination');
set local role authenticated;
update fixture set token_id=(public.blog_manage_token('veyocast','test','create',null,repeat('1',64),'Isolated test',array['capabilities:read','posts:read','posts:write','posts:publish','media:write'],now()+interval '1 hour')->>'id')::uuid;
select throws_ok($$select token_hash from private.platform_blog_tokens$$,'42501',null,'editor cannot read credential hashes');
select throws_ok($$select public.blog_command('veyocast','test','media.status',null,(select media from fixture),null,'unknown-media-key')$$,'PT404','NOT_FOUND','media status cannot create a new upload intent');
update fixture set intent=public.blog_command('veyocast','test','media.intent',null,media,null,'media-test-key-001');
select is((select intent#>>'{body,status}' from fixture),'pending','media intent persists before storage side effect');
select is(public.blog_command('veyocast','test','media.intent',null,(select media from fixture),null,'media-test-key-001'),(select intent from fixture),'media retry recovers same deterministic asset and path');
select throws_ok($$select public.blog_command('veyocast','test','media.complete',null,(select media from fixture),null,'media-test-key-001')$$,'PT403','PERMISSION_DENIED','editor cannot bypass the server decoder with direct completion');
select throws_ok($$select public.blog_complete_human_media('veyocast','test',(select media from fixture),'media-test-key-001','00000000-0000-4000-8000-000000313001')$$,'42501',null,'editor cannot call trusted server attestation directly');
select throws_ok($$select public.blog_command('veyocast','test','media.intent',null,(select media||'{"width":801}'::jsonb from fixture),null,'media-test-key-001')$$,'PT409','IDEMPOTENCY_CONFLICT','changed media under same key is rejected');
reset role;
set local role service_role;
select throws_ok($$select public.blog_complete_human_media('veyocast','test',(select media from fixture),'unknown-intent-key','00000000-0000-4000-8000-000000313001')$$,'PT404','NOT_FOUND','server completion cannot create an upload intent');
select throws_ok($$select public.blog_complete_human_media('veyocast','test',(select media from fixture),'media-test-key-001','00000000-0000-4000-8000-000000313002')$$,'PT403','PERMISSION_DENIED','another administrator cannot attest the original editor operation');
select throws_ok($$select public.blog_complete_human_media('veyocast','test',(select media||'{"width":801}'::jsonb from fixture),'media-test-key-001','00000000-0000-4000-8000-000000313001')$$,'PT409','IDEMPOTENCY_CONFLICT','server attestation binds the full verified metadata fingerprint');
select throws_ok($$select public.blog_complete_human_media('veyocast','test',(select media from fixture),'media-test-key-001','00000000-0000-4000-8000-000000313001')$$,'PT409','MEDIA_NOT_READY','server attestation requires the existing stored bytes');
reset role;
insert into storage.objects(bucket_id,name,metadata) select 'platform_blog_media',intent#>>'{body,storagePath}','{"size":1234,"mimetype":"image/png"}'::jsonb from fixture;
set local role service_role;
update fixture set media_receipt=public.blog_complete_human_media('veyocast','test',media,'media-test-key-001','00000000-0000-4000-8000-000000313001');
select is((select media_receipt->>'httpStatus' from fixture),'201','verified media completion has durable created response');
select is(public.blog_complete_human_media('veyocast','test',(select media from fixture),'media-test-key-001','00000000-0000-4000-8000-000000313001'),(select media_receipt from fixture),'trusted completion replays its original durable response');
reset role;
set local role authenticated;
select is(public.blog_command('veyocast','test','media.intent',null,(select media from fixture),null,'media-test-key-001'),(select media_receipt from fixture),'restarted upload returns original completion');
update fixture set payload=jsonb_set(payload,'{hero}',jsonb_build_object('assetId',intent#>>'{body,assetId}','alt','Een clubscherm met het wedstrijdprogramma.','focalPoint',jsonb_build_object('x',0.55,'y',0.4)));
select throws_ok($$select public.blog_command('veyocast','staging','upsert','campaign-a',(select payload from fixture),null,'foreign-env-write')$$,'PT400','INVALID_ASSET','assets cannot cross environment boundaries');
select throws_ok($$select public.blog_command('veyocast','test','upsert','invalid-content',(select jsonb_set(payload,'{content}','{"type":"doc","content":[{"type":"script"}]}') from fixture),null,'invalid-node-key')$$,'PT400','INVALID_REQUEST','unsupported executable node is rejected at database');
select throws_ok($$select public.blog_command('veyocast','test','upsert','invalid-link',(select jsonb_set(payload,'{content}','{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"unsafe","marks":[{"type":"link","attrs":{"href":"javascript:alert(1)"}}]}]}]}') from fixture),null,'invalid-link-key')$$,'PT400','INVALID_REQUEST','unsafe link is rejected independently of application');
reset role;
select lives_ok($$select private.blog_validate_payload((select jsonb_set(payload,'{content}','{"type":"doc","content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"type":"text","text":"VeyoCast","marks":[{"type":"link","attrs":{"href":"/","title":null}}]}]}]}') from fixture),'veyocast','test',false)$$,'safe homepage links and normalized nullable editor attributes survive database validation');
select throws_ok($$select private.blog_validate_payload((select jsonb_set(payload,'{content}','{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Unsafe origin","marks":[{"type":"link","attrs":{"href":"//foreign.example.test"}}]}]}]}') from fixture),'veyocast','test',false)$$,'PT400','INVALID_REQUEST','protocol-relative links cannot bypass the URL contract');
select throws_ok($$select private.blog_validate_payload((select payload||'{"untrusted":"field"}'::jsonb from fixture),'veyocast','test',false)$$,'PT400','INVALID_REQUEST','database rejects unknown article fields');
select throws_ok($$select private.blog_validate_payload((select payload||'{"slug":123}'::jsonb from fixture),'veyocast','test',true)$$,'PT400','INVALID_REQUEST','numeric slugs cannot produce a publication rejected by the public string schema');
select throws_ok($$select private.blog_validate_payload((select payload||'{"slug":true}'::jsonb from fixture),'veyocast','test',true)$$,'PT400','INVALID_REQUEST','boolean slugs cannot bypass the public string schema through JSON text extraction');
select throws_ok($$select private.blog_validate_payload((select jsonb_set(payload,'{content}','{"type":"doc","content":[{"type":"paragraph","attrs":{"onclick":"alert(1)"}}]}') from fixture),'veyocast','test',false)$$,'PT400','INVALID_REQUEST','unknown node attributes cannot reach published rendering');
select throws_ok($$select private.blog_validate_payload((select jsonb_set(payload,'{content}','{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Unsafe mark","marks":[{"type":"bold","attrs":{"onclick":"alert(1)"}}]}]}]}') from fixture),'veyocast','test',false)$$,'PT400','INVALID_REQUEST','plain marks cannot introduce attributes');
select throws_ok($$select private.blog_validate_payload((select jsonb_set(payload,'{content}','{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Exclusive inline code","marks":[{"type":"bold"},{"type":"code"}]}]}]}') from fixture),'veyocast','test',false)$$,'PT400','INVALID_REQUEST','exclusive code marks cannot create a document rejected by ProseMirror');
select throws_ok($$select private.blog_validate_payload((select jsonb_set(payload,'{content}','{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Unsafe link","marks":[{"type":"link","attrs":{"href":"https://example.test","target":"_blank"}}]}]}]}') from fixture),'veyocast','test',false)$$,'PT400','INVALID_REQUEST','link attributes follow the shared nullable target contract');
select throws_ok($$select private.blog_validate_payload((select jsonb_set(payload,'{content}','{"type":"doc","content":[{"type":"text","text":"Invalid top-level text"}]}') from fixture),'veyocast','test',false)$$,'PT400','INVALID_REQUEST','document children must be blocks');
select throws_ok($$select private.blog_validate_payload((select jsonb_set(payload,'{content}','{"type":"doc","content":[{"type":"bulletList","content":[{"type":"paragraph"}]}]}') from fixture),'veyocast','test',false)$$,'PT400','INVALID_REQUEST','list children must be list items');
select throws_ok($$select private.blog_validate_payload((select jsonb_set(payload,'{content}','{"type":"doc","content":[{"type":"table","content":[{"type":"tableRow","content":[{"type":"paragraph"}]}]}]}') from fixture),'veyocast','test',false)$$,'PT400','INVALID_REQUEST','table rows must contain actual cells');
select lives_ok($$select private.blog_validate_payload((select jsonb_set(payload,'{content}','{"type":"doc","content":[{"type":"table","content":[{"type":"tableRow","content":[{"type":"tableCell","attrs":{"colspan":1,"rowspan":1,"colwidth":null,"align":null},"content":[{"type":"paragraph","content":[{"type":"text","text":"Veilige tabel"}]}]}]}]}]}') from fixture),'veyocast','test',false)$$,'normalized TipTap table cells remain valid');
select lives_ok($$select private.blog_validate_payload((select payload||jsonb_build_object('slug',repeat('a',160)) from fixture),'veyocast','test',false)$$,'database accepts the shared maximum slug length');
select throws_ok($$select private.blog_validate_payload((select payload||jsonb_build_object('excerpt',repeat('a',601)) from fixture),'veyocast','test',false)$$,'PT400','INVALID_REQUEST','excerpt cannot exceed the shared six hundred character bound');
select throws_ok($$select private.blog_validate_payload((select payload||jsonb_build_object('seoTitle',repeat(U&'\+01F44D',101)) from fixture),'veyocast','test',false)$$,'PT400','INVALID_REQUEST','Unicode string bounds use the same UTF-16 units as the public validator');
select throws_ok($$select private.blog_validate_payload((select payload||'{"tags":[""]}'::jsonb from fixture),'veyocast','test',false)$$,'PT400','INVALID_REQUEST','empty tags are rejected');
select is(private.blog_safe_link('mailto://user:password@example.test'),false,'opaque contact links cannot introduce URL credentials');
select is(private.blog_safe_link('https://example.123'),false,'invalid WHATWG numeric host cannot become an unreadable live link');
select is(private.blog_safe_link('https://xn--a'),false,'unverified punycode host cannot bypass the public URL parser');
select throws_ok($$with recursive nesting(n,node) as (select 0,'{"type":"paragraph"}'::jsonb union all select n+1,jsonb_build_object('type','blockquote','content',jsonb_build_array(node)) from nesting where n<25) select private.blog_validate_payload((select jsonb_set(payload,'{content}',jsonb_build_object('type','doc','content',jsonb_build_array(node))) from fixture),'veyocast','test',false) from nesting where n=25$$,'PT400','INVALID_REQUEST','document depth cannot exceed the shared twenty-four level bound');
set local role authenticated;
update fixture set first_write=public.blog_command('veyocast','test','upsert','campaign-a',payload,null,'draft-test-key-001');
select is((select first_write#>>'{body,revision}' from fixture),'1','first draft receives immutable revision one');
select ok((select first_write#>>'{body,updatedAt}' is not null from fixture),'editor receives the real modification timestamp');
select lives_ok($$select public.blog_command('veyocast','test','upsert','incomplete',(select payload||'{"slug":"incompleet-artikel","title":"","hero":{"assetId":"","alt":"","focalPoint":{"x":0.5,"y":0.5}}}'::jsonb from fixture),null,'incomplete-draft-key')$$,'incomplete editorial fields remain saveable as a draft');
select throws_ok($$select public.blog_command('veyocast','test','publish','incomplete','{"revision":1}',1,'incomplete-publish-key')$$,'PT400','INVALID_REQUEST','incomplete draft cannot become public');
select is(jsonb_array_length(public.blog_command('veyocast','test','list',null,'{}',null,null)->'body'),2,'editor list reads actual stable articles');
select ok(public.blog_command('veyocast','test','status','campaign-a','{}',null,null)->'body' ? 'payload','authorized preview can read editable revision');
select is(public.blog_command('veyocast','test','upsert','campaign-a',(select payload from fixture),null,'draft-test-key-001'),(select first_write from fixture),'write timeout replay returns original accepted result');
select throws_ok($$select public.blog_command('veyocast','test','upsert','campaign-b',(select payload from fixture),null,'duplicate-slug-key')$$,'PT409','SLUG_CONFLICT','different external identity cannot steal reserved draft slug');
select throws_ok($$select public.blog_command('veyocast','test','upsert','campaign-a',(select payload from fixture),null,'missing-revision-key')$$,'PT412','REVISION_CONFLICT','existing external identity requires exact precondition');
reset role;
set local role anon;
select is((select count(*)::integer from public.platform_blog_publications),0,'draft absent from public list and detail source');
select is((select count(*)::integer from public.platform_blog_revisions),0,'direct revision access cannot reveal drafts');
select is((select count(*)::integer from public.platform_blog_assets),0,'draft-only media metadata is private');
select throws_ok($$select draft_revision from public.platform_blog_posts$$,'42501',null,'public reader cannot inspect draft pointer');
reset role;
set local role authenticated;
select set_config('request.jwt.claim.sub','00000000-0000-4000-8000-000000313004',true);
select is((select count(*)::integer from public.platform_blog_revisions),0,'tenant A cannot read platform draft');
select throws_ok($$select public.blog_command('veyocast','test','status','campaign-a','{}',null,null)$$,'PT403','PERMISSION_DENIED','tenant A cannot invoke platform edit or preview');
select throws_ok($$insert into public.platform_blog_posts(site_id,environment,external_id) values('veyocast','test','bypass')$$,'42501',null,'tenant A cannot bypass commands with table write');
select set_config('request.jwt.claim.sub','00000000-0000-4000-8000-000000313005',true);
select is((select count(*)::integer from public.platform_blog_revisions),0,'tenant B cannot read platform draft');
select set_config('request.jwt.claim.sub','00000000-0000-4000-8000-000000313003',true);
select throws_ok($$select public.blog_command('veyocast','test','list',null,'{}',null,null)$$,'PT403','PERMISSION_DENIED','platform viewer lacks editorial capability');
select set_config('request.jwt.claim.sub','00000000-0000-4000-8000-000000313002',true);
select set_config('request.jwt.claim.aal','aal1',true);
select throws_ok($$select public.blog_command('veyocast','test','publish','campaign-a','{"revision":1}',1,'publish-test-key-001')$$,'PT403','PERMISSION_DENIED','administrator AAL1 cannot publish');
select set_config('request.jwt.claim.aal','aal2',true);
update fixture set first_publish=public.blog_command('veyocast','test','publish','campaign-a','{"revision":1}',1,'publish-test-key-001');
select is((select first_publish#>>'{body,status}' from fixture),'published','administrator AAL2 publishes exact revision');
select is((select first_publish#>>'{body,publicUrl}' from fixture),'http://localhost:3002/blog/clubschermen-op-wedstrijddag','public response uses configured isolated marketing origin');
reset role;
set local role anon;
select is((select count(*)::integer from public.platform_blog_publications),1,'publish commit immediately changes public source');
select is((select payload->>'title' from public.platform_blog_publications),'Clubschermen op wedstrijddag','public detail reads published payload');
select is((select count(*)::integer from public.platform_blog_assets),1,'current publication authorizes only referenced media');
select is((select count(*)::integer from storage.objects where bucket_id='platform_blog_media'),0,'storage bytes never become anonymous bucket access');
reset role;
set local role authenticated;
select lives_ok($$select public.blog_command('veyocast','test','upsert','campaign-a',(select payload||'{"title":"Bijgewerkte wedstrijddag"}'::jsonb from fixture),1,'draft-test-key-002')$$,'new draft is a separate immutable revision');
select throws_ok($$select public.blog_command('veyocast','test','upsert','campaign-a',(select payload from fixture),1,'competing-draft-key')$$,'PT412','REVISION_CONFLICT','competing stale writer cannot overwrite newer draft');
select is(public.blog_command('veyocast','test','upsert','campaign-a',(select payload from fixture),null,'draft-test-key-001'),(select first_write from fixture),'original receipt replays before now-stale revision guard');
select is(public.blog_command('veyocast','test','publish','campaign-a','{"revision":1}',1,'publish-test-key-001'),(select first_publish from fixture),'publish replay survives newer draft and process restart');
select throws_ok($$select public.blog_command('veyocast','test','publish','campaign-a','{"revision":1}',1,'stale-publish-key')$$,'PT412','REVISION_CONFLICT','old queued publication cannot overwrite current approved revision');
select throws_ok($$select public.blog_command('veyocast','test','upsert','campaign-a',(select payload||'{"title":"Changed retry"}'::jsonb from fixture),null,'draft-test-key-001')$$,'PT409','IDEMPOTENCY_CONFLICT','changed retry cannot reuse original receipt');
reset role;
set local role anon;
select is((select payload->>'title' from public.platform_blog_publications),'Clubschermen op wedstrijddag','unpublished title edit leaves live article unchanged');
select is((select count(*)::integer from public.platform_blog_revisions),1,'public direct revision reads expose only currently live revision');
reset role;
set local role authenticated;
select lives_ok($$select public.blog_command('veyocast','test','upsert','campaign-a',(select payload||'{"slug":"actuele-clubschermen"}'::jsonb from fixture),2,'draft-test-key-003')$$,'explicit slug change prepares new draft');
select lives_ok($$select public.blog_command('veyocast','test','publish','campaign-a','{"revision":3}',3,'publish-test-key-003')$$,'slug pointer and publication switch in one command');
select throws_ok($$select public.blog_command('veyocast','test','upsert','campaign-b',(select payload from fixture),null,'historical-slug-key')$$,'PT409','SLUG_CONFLICT','historical slug cannot be reassigned');
reset role;
select throws_ok($$update public.platform_blog_revisions set payload='{}' where post_id=(select (first_write#>>'{body,id}')::uuid from fixture)$$,'PT409','IMMUTABLE_REVISION','even privileged accidental revision rewrite is rejected');
select is((select count(*)::integer from public.platform_blog_posts where external_id='campaign-a'),1,'all writes and retries retain one stable article identity');
select is((select count(*)::integer from public.platform_blog_assets),1,'all upload retries retain one asset');
set local role anon;
select is((select slug from public.platform_blog_publications),'actuele-clubschermen','current canonical slug comes from confirmed publication');
select is((select p.canonical_slug from public.platform_blog_routes r join public.platform_blog_posts p on p.id=r.post_id where r.slug='clubschermen-op-wedstrijddag'),'actuele-clubschermen','historical route resolves directly to current canonical slug');
reset role;
set local role service_role;
select throws_ok($$select public.blog_authorize_token(null,'veyocast','test','capabilities:read')$$,'PT401','INVALID_CREDENTIAL','missing credential fails closed');
select throws_ok($$select public.blog_authorize_token(repeat('9',64),'veyocast','test','capabilities:read')$$,'PT401','INVALID_CREDENTIAL','unknown credential fails closed');
select throws_ok($$select public.blog_authorize_token(repeat('1',64),'veyocast','staging','capabilities:read')$$,'PT403','PERMISSION_DENIED','credential cannot cross environment');
select is(public.blog_authorize_token(repeat('1',64),'veyocast','test','capabilities:read')->>'allowed','true','read-only connection probe uses scoped credential');
select is(public.blog_authorize_token(repeat('1',64),'veyocast','test','capabilities:read')->>'publicOrigin','http://localhost:3002','token preflight binds API runtime to the configured public destination');
select is(public.blog_command('veyocast','test','status','campaign-a','{}',null,null,repeat('1',64))#>>'{body,publishedRevision}','3','API status reads exact confirmed revision');
select ok(not (public.blog_command('veyocast','test','status','campaign-a','{}',null,null,repeat('1',64))->'body' ? 'payload'),'API status excludes private draft document');
select throws_ok($$select * from private.platform_blog_tokens$$,'42501',null,'service route cannot fetch stored hash table directly');
select count(public.blog_authorize_token(repeat('1',64),'veyocast','test','capabilities:read')) from generate_series(1,119);
select is(public.blog_authorize_token(repeat('1',64),'veyocast','test','capabilities:read')->>'code','RATE_LIMITED','durable read rate limit rejects the next expensive dispatch');
reset role;
select is((select count(*)::integer from private.platform_blog_rate_limits),1,'rate limiter cardinality stays bounded per credential and scope');
select is((select requests from private.platform_blog_rate_limits),121,'rate counter saturates at bounded denied value');
insert into private.platform_blog_tokens(site_id,environment,token_hash,label,scopes,expires_at) values
 ('veyocast','test',repeat('2',64),'Read only',array['capabilities:read'],now()+interval '1 hour'),
 ('veyocast','test',repeat('3',64),'Expired',array['capabilities:read'],now()-interval '1 hour');
set local role service_role;
select throws_ok($$select public.blog_command('veyocast','test','upsert','denied',(select payload from fixture),null,'denied-scope-key',repeat('2',64))$$,'PT403','PERMISSION_DENIED','read-only credential cannot write');
select throws_ok($$select public.blog_authorize_token(repeat('3',64),'veyocast','test','capabilities:read')$$,'PT401','INVALID_CREDENTIAL','expired token is rejected');
reset role;
set local role authenticated;
select lives_ok($$select public.blog_manage_token('veyocast','test','rotate',(select token_id from fixture),repeat('4',64),'Replacement',array['capabilities:read','posts:read','posts:write','posts:publish','media:write'],now()+interval '1 hour')$$,'credential rotates and revokes old hash atomically');
reset role;
set local role service_role;
select throws_ok($$select public.blog_authorize_token(repeat('1',64),'veyocast','test','capabilities:read')$$,'PT401','INVALID_CREDENTIAL','rotated credential cannot replay an old write');
select is(public.blog_command('veyocast','test','publish','campaign-a','{"revision":1}',1,'publish-test-key-001',repeat('4',64)),(select first_publish from fixture),'authorized replacement token can recover destination receipt');
update fixture set api_intent=public.blog_command('veyocast','test','media.intent',null,media,null,'api-media-test-key',repeat('4',64));
select throws_ok($$select public.blog_complete_human_media('veyocast','test',(select media from fixture),'api-media-test-key','00000000-0000-4000-8000-000000313001')$$,'PT403','PERMISSION_DENIED','human attestation cannot complete a machine-owned intent');
reset role;
insert into storage.objects(bucket_id,name,metadata) select 'platform_blog_media',api_intent#>>'{body,storagePath}','{"size":1234,"mimetype":"image/png"}'::jsonb from fixture;
set local role service_role;
update fixture set api_receipt=public.blog_command('veyocast','test','media.complete',null,media,null,'api-media-test-key',repeat('4',64));
select is((select api_receipt->>'httpStatus' from fixture),'201','scoped service credential completes decoded API media');
select is(public.blog_command('veyocast','test','media.intent',null,(select media from fixture),null,'api-media-test-key',repeat('4',64)),(select api_receipt from fixture),'API media replay recovers the original complete response');
reset role;
set local role anon;
select is((select count(*)::integer from public.platform_blog_assets),1,'ready but unpublished API media remains private');
reset role;
set local role authenticated;
select lives_ok($$select public.blog_command('veyocast','test','upsert','publication-guards',(select payload||'{"slug":"publication-guards"}'::jsonb from fixture),null,'publication-guard-draft-1')$$,'publication guard fixture prepares a valid article');
select lives_ok($$select public.blog_command('veyocast','test','publish','publication-guards','{"revision":1}',1,'publication-guard-publish-1')$$,'valid initial publication succeeds');
select lives_ok($$select public.blog_command('veyocast','test','upsert','publication-guards',(select payload||'{"slug":"publication-guards","seoTitle":"","seoDescription":""}'::jsonb from fixture),1,'publication-guard-draft-2')$$,'empty SEO remains editable as a private draft');
select throws_ok($$select public.blog_command('veyocast','test','publish','publication-guards','{"revision":2}',2,'publication-guard-publish-2')$$,'PT400','INVALID_REQUEST','empty SEO cannot produce a confirmed but unreadable publication');
select lives_ok($$select public.blog_command('veyocast','test','upsert','publication-guards',(select payload||'{"slug":"publication-guards","content":{"type":"doc","content":[{"type":"paragraph"}]}}'::jsonb from fixture),2,'publication-guard-draft-3')$$,'an empty paragraph remains a saveable draft');
select throws_ok($$select public.blog_command('veyocast','test','publish','publication-guards','{"revision":3}',3,'publication-guard-publish-3')$$,'PT400','INVALID_REQUEST','an empty paragraph cannot masquerade as published article content');
select lives_ok($$select public.blog_command('veyocast','test','upsert','publication-guards',(select jsonb_set(payload||'{"slug":"publication-guards"}'::jsonb,'{content}','{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"\u00a0\ufeff"}]}]}'::jsonb) from fixture),3,'publication-guard-draft-4')$$,'Unicode whitespace remains editable without being treated as public content');
select throws_ok($$select public.blog_command('veyocast','test','publish','publication-guards','{"revision":4}',4,'publication-guard-publish-4')$$,'PT400','INVALID_REQUEST','Unicode-only whitespace fails the same content check as JavaScript trim');
reset role;
set local role anon;
select is((select revision from public.platform_blog_publications where external_id='publication-guards'),1::bigint,'all failed publications preserve the previously valid live revision');
reset role;
select is((select count(*)::integer from public.audit_events where action='platform.blog.publish' and target_id=(select (first_write#>>'{body,id}')::uuid from fixture)),2,'only distinct committed publications emit audit entries');
select lives_ok($$set constraints platform_blog_draft_revision_fk,platform_blog_published_revision_fk,platform_blog_canonical_route_fk immediate$$,'all revision and canonical route pointers satisfy their commit constraints');
select * from finish();
rollback;
